final scroll = useScrollController();
final rowKeys = useRef(<String, GlobalKey>{}).value;

// Keep VoidScreen informed about the current viewport so it can decide
// whether the playing track row is off-screen.
useEffect(() {
  if (browserController == null) return null;

  void updateMetrics() {
    if (!scroll.hasClients) return;
    final pos = scroll.position;
    browserController!.scrollMetricsNotifier.value =
        BrowserScrollMetrics(
      offset: pos.pixels,
      viewportDimension: pos.viewportDimension,
    );
  }

  WidgetsBinding.instance.addPostFrameCallback((_) => updateMetrics());
  updateMetrics();
  scroll.addListener(updateMetrics);
  return () => scroll.removeListener(updateMetrics);
}, [browserController, scroll]);

